<!doctype html><html lang="{{ session('portal_lang','en') }}"><head><meta name="rpos-print-document" content="kot"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{{ t('Kitchen ticket','কিচেন টিকিট') }} · {{ $orderData['order_no'] }}</title><style>body{font-family:Arial,sans-serif;background:#f3f4f6;color:#111;margin:0;padding:24px}.ticket{width:min(420px,100%);margin:0 auto 20px;background:#fff;padding:22px;box-sizing:border-box;border:1px solid #ddd;border-radius:10px}h1{font-size:20px;margin:0 0 8px}h2{font-size:17px;margin:16px 0 6px}p{font-size:12px;line-height:1.6;margin:6px 0}.ticket-line{border-top:1px dashed #aaa;padding:12px 0}.food{display:flex;justify-content:space-between;gap:10px;font-size:16px;font-weight:700}.note{background:#f5f5f5;padding:8px;margin-top:8px;font-size:13px}.actions{text-align:center;margin-bottom:20px}.actions button,.actions a{padding:10px 15px;border:1px solid #ccc;border-radius:7px;background:white;color:#111;text-decoration:none;font-size:13px;cursor:pointer}.muted{color:#666}.empty{text-align:center;padding:25px}@media print{body{background:#fff;padding:0}.actions{display:none}.ticket{width:78mm;margin:0;border:0;border-radius:0;padding:3mm;break-after:page}.ticket:last-child{break-after:auto}.ticket-line{break-inside:avoid}.note{background:none;border:1px solid #bbb}@page{margin:3mm}}body.rpos-print-embedded{padding:16px;background:#eef0f4;color-scheme:light}@media print{body.rpos-print-embedded{padding:0;background:#fff}}</style></head><body @if(request()->boolean('embed')) class="rpos-print-embedded" @endif>
