<article class="ticket"><h1>{{ $business->name }}</h1><p>{{ t('Kitchen ticket','কিচেন টিকিট') }} · <strong>{{ $orderData['order_no'] }}</strong> · @if((int)($first['kitchen_batch'] ?? 0)>0){{ t('Batch','ব্যাচ') }} {{ $first['kitchen_batch'] }}@else{{ t('Print only','শুধু প্রিন্ট') }}@endif</p><h2>{{ t($first['kitchen_station_name'] ?? 'General kitchen',$first['kitchen_station_name_bn'] ?? 'সাধারণ কিচেন') }}</h2><p>{{ $types[$orderData['service_type']] ?? $orderData['service_type'] }}@if($orderData['table'] ?? null) · {{ t($orderData['table']['name'],$orderData['table']['name_bn'] ?? null) }}@endif · {{ t('Guests','অতিথি') }}: {{ $orderData['guest_count'] }}</p><p class="muted">{{ $first['sent_at'] ?? $order->updated_at?->format('d M Y, h:i A') }}</p>
